package com.company.platform.aigateway.orchestration;import java.util.*;import org.springframework.stereotype.Component;@Component public class PluginRegistry{private final Map<UUID,PluginDescriptor> plugins=new HashMap<>();public PluginDescriptor register(PluginDescriptor p){if(p==null||p.tenantId()==null)throw new IllegalArgumentException("plugin tenant required");plugins.put(p.id(),p);return p;}public List<PluginDescriptor> list(UUID tenant){return plugins.values().stream().filter(x->tenant.equals(x.tenantId())).toList();}}
